from cache import peek
from decoder import decode
from policy import can_dispatch
from z_worker import dispatch


def handle(raw, cache):
    request = decode(raw)
    if request is None:
        return 'invalid'
    key, dry_run = request
    saved = peek(cache, key)
    if saved is not None:
        return saved
    if not can_dispatch(dry_run):
        return 'blocked'
    return dispatch(key)

