def allowance(tier, batch, burst, credit):
    amount = 4
    if tier == 'pro':
        amount += 7
    elif tier == 'trial':
        amount -= 3
    if batch:
        amount += 5
    elif burst:
        amount += 2
    amount = min(12, amount)
    if credit and tier != 'trial':
        amount -= 6
    return amount

