def publish(job, store, send):
    if store.was_sent(job['id']):
        return 'duplicate'
    try:
        send(job)
    except TimeoutError:
        store.mark_retry(job['id'])
        return 'retry'
    store.mark_sent(job['id'])
    return 'sent'

