from publisher import publish


class FakeStore:
    def __init__(self):
        self.retries = []
        self.sent = []

    def was_sent(self, key):
        return key in self.sent

    def mark_retry(self, key):
        self.retries.append(key)

    def mark_sent(self, key):
        self.sent.append(key)


def timeout(job):
    raise TimeoutError(job['id'])


def test_timeout():
    store = FakeStore()
    assert publish({'id': 'A'}, store, timeout) == 'retry'
    assert store.retries == ['A']
    assert store.sent == []
